{"path":"/workspace/lib/books.ts","content":"import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import path from "node:path";

export const limits = {
  title: 200,
  author: 200,
  notes: 10_000,
} as const;

export const formErrorMessage = {
  title: "Enter a title.",
  author: "Enter an author.",
  titleLength: "Title must be 200 characters or fewer.",
  authorLength: "Author must be 200 characters or fewer.",
  notesLength: "Notes must be 10,000 characters or fewer.",
  save: "Could not add the book.",
} as const;

export type FormErrorCode = keyof typeof formErrorMessage;
export type InputErrorCode = Exclude<FormErrorCode, "save">;

export type BookStatus = "reading" | "finished";

export type Book = {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: BookStatus;
  createdAt: string;
  finishedAt: string | null;
};

export type CreateBookResult =
  | { ok: true; book: Book }
  | { ok: false; error: InputErrorCode };

// Books live in a JSON file so they survive restarts. Tests set BOOKS_FILE.
function dataFile() {
  return process.env.BOOKS_FILE ?? path.join(process.cwd(), "data", "books.json");
}

let writeQueue: Promise<unknown> = Promise.resolve();

function enqueue<T>(task: () => Promise<T>): Promise<T> {
  const run = writeQueue.then(task, task);
  writeQueue = run.then(
    () => undefined,
    () => undefined,
  );
  return run;
}

function isNodeError(error: unknown): error is NodeJS.ErrnoException {
  return error instanceof Error && "code" in error;
}

function isBook(value: unknown): value is Book {
  if (typeof value !== "object" || value === null) return false;
  const book = value as Record<string, unknown>;
  return (
    typeof book.id === "string" &&
    book.id.length > 0 &&
    typeof book.title === "string" &&
    typeof book.author === "string" &&
    typeof book.notes === "string" &&
    (book.status === "reading" || book.status === "finished") &&
    typeof book.createdAt === "string" &&
    (book.finishedAt === null || typeof book.finishedAt === "string")
  );
}

async function readBooks(): Promise<Book[]> {
  let raw: string;
  try {
    raw = await readFile(dataFile(), "utf8");
  } catch (error) {
    if (isNodeError(error) && error.code === "ENOENT") return [];
    throw new Error("The books file could not be read.", { cause: error });
  }

  if (!raw.trim()) return [];

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw new Error("The books file could not be read.", { cause: error });
  }

  if (!Array.isArray(parsed) || !parsed.every(isBook)) {
    throw new Error("The books file could not be read.");
  }

  return parsed;
}

async function writeBooks(books: Book[]) {
  const file = dataFile();
  await mkdir(path.dirname(file), { recursive: true });
  const tmp = `${file}.${process.pid}.${randomUUID()}.tmp`;
  try {
    await writeFile(tmp, `${JSON.stringify(books, null, 2)}\n`, "utf8");
    await rename(tmp, file);
  } catch (error) {
    await rm(tmp, { force: true });
    throw error;
  }
}

export function listBooks() {
  return readBooks();
}

export async function shelf() {
  const books = await readBooks();
  const reading = books
    .filter((book) => book.status === "reading")
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  const finished = books
    .filter((book) => book.status === "finished")
    .sort((a, b) =>
      (b.finishedAt ?? b.createdAt).localeCompare(a.finishedAt ?? a.createdAt),
    );
  return { reading, finished };
}

export async function getBook(id: string) {
  const books = await readBooks();
  return books.find((book) => book.id === id) ?? null;
}

export function createBook(input: { title: string; author: string; notes: string }) {
  return enqueue(async (): Promise<CreateBookResult> => {
    const title = input.title.trim();
    const author = input.author.trim();
    const notes = input.notes.trim();

    if (!title) return { ok: false, error: "title" };
    if (!author) return { ok: false, error: "author" };
    if (title.length > limits.title) return { ok: false, error: "titleLength" };
    if (author.length > limits.author) return { ok: false, error: "authorLength" };
    if (notes.length > limits.notes) return { ok: false, error: "notesLength" };

    const book: Book = {
      id: randomUUID(),
      title,
      author,
      notes,
      status: "reading",
      createdAt: new Date().toISOString(),
      finishedAt: null,
    };

    const books = await readBooks();
    books.push(book);
    await writeBooks(books);
    return { ok: true, book };
  });
}

export function finishBook(id: string) {
  return enqueue(async () => {
    if (!id) return null;
    const books = await readBooks();
    const book = books.find((item) => item.id === id);
    if (!book) return null;
    if (book.status !== "finished") {
      book.status = "finished";
      book.finishedAt = new Date().toISOString();
      await writeBooks(books);
    }
    return book;
  });
}
"}

{"path":"/workspace/lib/format.ts","content":"export function formatDate(value: string | null) {
  if (!value) return null;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  return new Intl.DateTimeFormat("en", {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(date);
}
"}

{"path":"/workspace/lib/books.test.ts","content":"import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, beforeEach, expect, test } from "vitest";
import { createBook, finishBook, getBook, listBooks, shelf } from "./books";

let directory: string;

beforeEach(async () => {
  directory = await mkdtemp(path.join(tmpdir(), "reading-list-"));
  process.env.BOOKS_FILE = path.join(directory, "books.json");
});

afterEach(async () => {
  delete process.env.BOOKS_FILE;
  await rm(directory, { recursive: true, force: true });
});

test("starts empty when the file is missing", async () => {
  await expect(listBooks()).resolves.toEqual([]);
});

test("saves a book to the json file and reads it back", async () => {
  const created = await createBook({
    title: "  Kindred  ",
    author: " Octavia E. Butler ",
    notes: "  Reread the ending.  ",
  });

  expect(created.ok).toBe(true);
  if (!created.ok) return;

  expect(created.book).toMatchObject({
    title: "Kindred",
    author: "Octavia E. Butler",
    notes: "Reread the ending.",
    status: "reading",
    finishedAt: null,
  });

  const raw = await readFile(process.env.BOOKS_FILE!, "utf8");
  const stored = JSON.parse(raw) as Array<{ id: string; status: string }>;
  expect(stored).toHaveLength(1);
  expect(stored[0]?.id).toBe(created.book.id);
  expect(stored[0]?.status).toBe("reading");

  await expect(getBook(created.book.id)).resolves.toMatchObject({
    title: "Kindred",
  });
  await expect(getBook("missing")).resolves.toBeNull();
});

test("rejects a blank title without writing a file", async () => {
  await expect(
    createBook({ title: "   ", author: "Author", notes: "notes" }),
  ).resolves.toEqual({ ok: false, error: "title" });
  await expect(readFile(process.env.BOOKS_FILE!, "utf8")).rejects.toThrow();
});

test("marks a book finished and keeps it after another read", async () => {
  const created = await createBook({
    title: "Piranesi",
    author: "Susanna Clarke",
    notes: "",
  });
  if (!created.ok) throw new Error("expected book");

  const finished = await finishBook(created.book.id);
  expect(finished?.status).toBe("finished");
  expect(finished?.finishedAt).toEqual(expect.any(String));

  const again = await finishBook(created.book.id);
  expect(again?.finishedAt).toBe(finished?.finishedAt);

  const grouped = await shelf();
  expect(grouped.reading).toEqual([]);
  expect(grouped.finished.map((book) => book.id)).toEqual([created.book.id]);
});

test("keeps every book when adds overlap", async () => {
  await Promise.all([
    createBook({ title: "A", author: "One", notes: "" }),
    createBook({ title: "B", author: "Two", notes: "" }),
    createBook({ title: "C", author: "Three", notes: "note" }),
  ]);

  const books = await listBooks();
  expect(books.map((book) => book.title).sort()).toEqual(["A", "B", "C"]);
});

test("reads whatever is currently in the file", async () => {
  const book = {
    id: "hand-edited",
    title: "The Dispossessed",
    author: "Ursula K. Le Guin",
    notes: "Added by hand.",
    status: "reading",
    createdAt: "2026-01-02T00:00:00.000Z",
    finishedAt: null,
  };
  await writeFile(process.env.BOOKS_FILE!, JSON.stringify([book]), "utf8");

  await expect(listBooks()).resolves.toEqual([book]);
});

test("refuses a corrupt books file", async () => {
  await writeFile(process.env.BOOKS_FILE!, "{", "utf8");
  await expect(listBooks()).rejects.toThrow("The books file could not be read.");
});
"}

{"path":"/workspace/app/actions.ts","content":""use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { createBook, finishBook } from "@/lib/books";

export async function addBook(formData: FormData) {
  const title = String(formData.get("title") ?? "");
  const author = String(formData.get("author") ?? "");
  const notes = String(formData.get("notes") ?? "");

  let result;
  try {
    result = await createBook({ title, author, notes });
  } catch (error) {
    console.error(error);
    redirect("/?error=save");
  }

  if (!result.ok) {
    redirect(`/?error=${result.error}`);
  }

  revalidatePath("/");
  revalidatePath(`/books/${result.book.id}`);
  redirect(`/books/${result.book.id}`);
}

export async function markFinished(formData: FormData) {
  const id = String(formData.get("id") ?? "");

  let book;
  try {
    book = await finishBook(id);
  } catch (error) {
    console.error(error);
    redirect("/");
  }

  revalidatePath("/");
  if (id) revalidatePath(`/books/${id}`);
  if (!book) redirect("/");
}
"}

