{"path":"/workspace/app/globals.css","content":":root {
  color-scheme: light;
  --bg: #f3eee4;
  --paper: #fffdf8;
  --ink: #1d1a16;
  --muted: #6d6458;
  --line: #e4d9c8;
  --accent: #1e4a38;
  --accent-strong: #16382b;
  --danger: #8d3d2c;
  --field: #fff;
  --field-line: #d8cebf;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(900px 420px at 0% -10%, #f8f3ea, transparent 55%),
    var(--bg);
  color: var(--ink);
  font-family: "Segoe UI", "Avenir Next", "Helvetica Neue", sans-serif;
  line-height: 1.5;
}

::selection {
  background: #d5e6dc;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

a {
  color: inherit;
}

.shell {
  width: min(920px, calc(100% - 2rem));
  margin: 0 auto;
  padding: 2.5rem 0 4rem;
}

h1,
h2,
h3,
.byline {
  font-family: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  font-weight: 600;
  letter-spacing: -0.02em;
}

h1 {
  margin: 0;
  font-size: clamp(2rem, 4vw, 2.7rem);
  line-height: 1.1;
}

h2 {
  margin: 0 0 0.9rem;
  font-size: 1.35rem;
}

h3 {
  margin: 0;
  font-size: 1.2rem;
  line-height: 1.3;
}

.intro {
  margin-bottom: 0.4rem;
}

.lede,
.muted,
.hint,
.meta,
.author {
  color: var(--muted);
}

.lede {
  margin: 0.45rem 0 0;
  max-width: 38rem;
}

.home,
.book {
  display: grid;
  gap: 1rem;
}

.panel {
  background: var(--paper);
