"use client";

import { useState } from "react";

export function CopyLink({ url }: { url: string }) {
  const [message, setMessage] = useState(
    "Anyone who can open this app can view this book at this address.",
  );

  async function onCopy() {
    const link = window.location.href || url;
    try {
      await navigator.clipboard.writeText(link);
      setMessage("Link copied.");
    } catch {
      setMessage("Select the link above and copy it.");
    }
  }

  return (
    <div className="share">
      <a className="share-url" href={url}>
        {url}
      </a>
      <button type="button" className="button secondary" onClick={onCopy}>
        Copy link
      </button>
      <p className="hint">{message}</p>
    </div>
  );
}

