import Link from "next/link";
import { FinishForm } from "@/components/finish-form";
import { SubmitButton } from "@/components/submit-button";
import { addBook } from "@/app/actions";
import { formatDate } from "@/lib/format";
import {
  formErrorMessage,
  limits,
  shelf,
  type Book,
  type FormErrorCode,
} from "@/lib/books";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

type HomePageProps = {
  searchParams: Promise<{ error?: string | string[] }>;
};

function errorMessage(error: string | string[] | undefined) {
  const code = Array.isArray(error) ? error[0] : error;
  if (!code || !(code in formErrorMessage)) return null;
  return formErrorMessage[code as FormErrorCode];
}

function BookList({
  books,
  empty,
  showFinish,
}: {
  books: Book[];
  empty: string;
  showFinish: boolean;
}) {
  if (books.length === 0) {
    return <p className="muted">{empty}</p>;
  }

  return (
    <ul className="book-list">
      {books.map((book) => {
        const added = formatDate(book.createdAt);
        const finished = formatDate(book.finishedAt);
        return (
          <li key={book.id} className="book-card">
            <Link className="book-link" href={`/books/${book.id}`}>
              <h3>{book.title}</h3>
              <p className="author">by {book.author}</p>
              <p className="meta">
                {showFinish
                  ? added
                    ? `Added ${added}`
                    : "In progress"
                  : finished
                    ? `Finished ${finished}`
                    : "Finished"}
              </p>
            </Link>
            {showFinish ? <FinishForm id={book.id} /> : null}
          </li>
        );
      })}
    </ul>
  );
}

export default async function HomePage({ searchParams }: HomePageProps) {
  const { error } = await searchParams;
  const message = errorMessage(error);
  const { reading, finished } = await shelf();

  return (
    <main className="home">
      <header className="intro">
        <h1>Reading list</h1>
        <p className="lede">What you're reading now, and what you've finished.</p>
      </header>

      <section className="panel" aria-labelledby="add-heading">
        <h2 id="add-heading">Add a book</h2>
        <form action={addBook} className="add-form">
          <div className="field-row">
            <label htmlFor="title">
              Title
              <input
                id="title"
                name="title"
                required
                maxLength={limits.title}
                autoComplete="off"
              />
            </label>
            <label htmlFor="author">
              Author
              <input
                id="author"
                name="author"
                required
                maxLength={limits.author}
                autoComplete="off"
              />
            </label>
          </div>
          <label htmlFor="notes">
            <span>
              Notes <span className="optional">optional</span>
            </span>
            <textarea id="notes" name="notes" rows={4} maxLength={limits.notes} />
          </label>
          {message ? (
            <p className="error" role="alert">
              {message}
            </p>
          ) : null}
          <SubmitButton pendingLabel="Adding...">Add book</SubmitButton>
        </form>
      </section>

      <div className="columns">
        <section className="panel" aria-labelledby="reading-heading">
          <h2 id="reading-heading">
            Currently reading <span className="count">{reading.length}</span>
          </h2>
          <BookList books={reading} empty="Nothing in progress." showFinish />
        </section>
        <section className="panel" aria-labelledby="finished-heading">
          <h2 id="finished-heading">
            Finished <span className="count">{finished.length}</span>
          </h2>
          <BookList books={finished} empty="None finished yet." showFinish={false} />
        </section>
      </div>
    </main>
  );
}

import Link from "next/link";
import { headers } from "next/headers";
import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { CopyLink } from "@/components/copy-link";
import { FinishForm } from "@/components/finish-form";
import { formatDate } from "@/lib/format";
import { getBook } from "@/lib/books";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

type BookPageProps = {
  params: Promise<{ id: string }>;
};

async function shareOrigin() {
  const headerList = await headers();
  const host =
    headerList.get("x-forwarded-host")?.split(",")[0]?.trim() ||
    headerList.get("host");
  if (!host) return "";
  const proto =
    headerList.get("x-forwarded-proto")?.split(",")[0]?.trim() || "http";
  return `${proto}://${host}`;
}

export async function generateMetadata({ params }: BookPageProps): Promise<Metadata> {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) return { title: "Book not found" };

  const description = book.notes
    ? book.notes.slice(0, 180)
    : `By ${book.author}`;

  return {
    title: book.title,
    description,
    openGraph: {
      title: book.title,
      description,
    },
  };
}

export default async function BookPage({ params }: BookPageProps) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();

  const origin = await shareOrigin();
  const shareUrl = origin ? `${origin}/books/${book.id}` : `/books/${book.id}`;
  const added = formatDate(book.createdAt);
  const finished = formatDate(book.finishedAt);
  const status =
    book.status === "reading"
      ? "Currently reading"
      : finished
        ? `Finished ${finished}`
        : "Finished";

  return (
    <main className="book">
      <p className="back-row">
        <Link className="back" href="/">
          All books
        </Link>
      </p>

      <header className="book-header">
        <h1>{book.title}</h1>
        <p className="byline">by {book.author}</p>
        <p className="meta">
          {status}
          {added ? ` · Added ${added}` : null}
        </p>
        {book.status === "reading" ? <FinishForm id={book.id} /> : null}
      </header>

      <section className="panel" aria-labelledby="notes-heading">
        <h2 id="notes-heading">Notes</h2>
        {book.notes ? (
          <p className="notes">{book.notes}</p>
        ) : (
          <p className="muted">No notes yet.</p>
        )}
      </section>

      <section className="panel" aria-labelledby="share-heading">
        <h2 id="share-heading">Share</h2>
        <CopyLink url={shareUrl} />
      </section>
    </main>
  );
}

